import json, os, subprocess, hashlib
from pathlib import Path

source=Path("/Users/steventran/do-again")
target=Path("/Users/steventran/Sonary")
req_id="sonary-daw-typecheck-stage-isolation-20261008-143"

env=os.environ.copy()
env["PYTHONPATH"]=str(source/"src")

def run(args, timeout=240):
    return subprocess.run(args,cwd=source,text=True,capture_output=True,check=False,env=env,timeout=timeout)

key=hashlib.sha256(str(target.resolve()).encode()).hexdigest()[:12]
root=Path.home()/".do_again/projects"/key
receipt=root/"control/automation/do_again/receipts"/f"{req_id}.json"
ledger=root/"state/ledger"/f"{req_id}.json"

before_ledger=json.loads(ledger.read_text()) if ledger.is_file() else None
if not isinstance(before_ledger,dict) or before_ledger.get("state")!="started":
    raise SystemExit(f"precondition failed: expected started ledger, got {before_ledger}")
if receipt.exists():
    raise SystemExit("precondition failed: receipt already exists")

p=run(["python3","-m","do_again.cli","run",str(target),"--once"])
print("=== recovery stdout ===")
print(p.stdout)
print("=== recovery stderr ===")
print(p.stderr)
print("recovery_rc="+str(p.returncode))
if p.returncode!=0:
    raise SystemExit("supported once recovery failed")

if not receipt.is_file():
    raise SystemExit("recovery did not publish terminal receipt")

r=json.loads(receipt.read_text())
after_ledger=json.loads(ledger.read_text()) if ledger.is_file() else {}

print(json.dumps({
  "receipt":r,
  "ledger":after_ledger,
},indent=2,sort_keys=True))

if r.get("state")!="blocked_ambiguous_replay":
    raise SystemExit(f"unexpected recovered receipt state: {r.get('state')}")
if "prior agent instance began this request" not in str(r.get("error","")).lower():
    raise SystemExit(f"missing ambiguous replay safety reason: {r.get('error')}")
if after_ledger.get("state")!="terminal":
    raise SystemExit(f"ledger not terminal after recovery: {after_ledger}")
stored=after_ledger.get("receipt") or {}
if stored.get("state")!="blocked_ambiguous_replay":
    raise SystemExit("terminal ledger does not preserve ambiguous-replay receipt")

print("SONARY_STALE_STARTED_RECOVERY_ACCEPTANCE_OK")
